-- =====================================================================
-- Ponto A – Restaurante e Pizzaria
-- Entrega 2 – Script SQL completo (MySQL 8, InnoDB, utf8mb4)
--
-- Ordem do script:
--   1. CREATE DATABASE
--   2. CREATE TABLE (19 tabelas) e constraints (PK, FK, NOT NULL, UNIQUE, CHECK, DEFAULT)
--   3. INSERT INTO (massa de dados fictícia)
--   4. SELECT com JOIN
--   5. UPDATE
--   6. DELETE
--   7. Consultas gerenciais (G01 a G16)
--   8. Consultas de auditoria (A01 a A18)
--
-- Para executar: mysql -u root -p < script.sql   (o banco é recriado do zero)
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. CREATE DATABASE
-- ---------------------------------------------------------------------
DROP DATABASE IF EXISTS ponto_a;
CREATE DATABASE ponto_a CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ponto_a;

-- ---------------------------------------------------------------------
-- 2. CREATE TABLE e constraints
-- Todas as chaves estrangeiras usam RESTRICT: o histórico de visitas,
-- pedidos, pagamentos e estoque não pode ser apagado.
-- ---------------------------------------------------------------------

CREATE TABLE ambiente (
    id_ambiente        INT AUTO_INCREMENT,
    nome_ambiente      VARCHAR(60)  NOT NULL,
    capacidade_maxima  INT          NOT NULL,
    status             VARCHAR(10)  NOT NULL DEFAULT 'ativo',
    CONSTRAINT pk_ambiente PRIMARY KEY (id_ambiente),
    CONSTRAINT uq_ambiente_nome UNIQUE (nome_ambiente),
    CONSTRAINT ck_ambiente_capacidade CHECK (capacidade_maxima > 0),
    CONSTRAINT ck_ambiente_status CHECK (status IN ('ativo', 'inativo'))
) ENGINE=InnoDB;

CREATE TABLE mesa (
    id_mesa      INT AUTO_INCREMENT,
    numero       INT NOT NULL,
    id_ambiente  INT NOT NULL,
    CONSTRAINT pk_mesa PRIMARY KEY (id_mesa),
    CONSTRAINT uq_mesa_numero UNIQUE (numero),
    CONSTRAINT fk_mesa_ambiente FOREIGN KEY (id_ambiente) REFERENCES ambiente (id_ambiente)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE visita (
    id_visita             INT AUTO_INCREMENT,
    data_hora_abertura    DATETIME    NOT NULL,
    data_hora_fechamento  DATETIME    NULL,
    status                VARCHAR(10) NOT NULL DEFAULT 'aberta',
    CONSTRAINT pk_visita PRIMARY KEY (id_visita),
    CONSTRAINT ck_visita_status CHECK (status IN ('aberta', 'fechada')),
    CONSTRAINT ck_visita_fechamento CHECK (
        (status = 'aberta' AND data_hora_fechamento IS NULL)
        OR (status = 'fechada' AND data_hora_fechamento IS NOT NULL
            AND data_hora_fechamento >= data_hora_abertura)
    )
) ENGINE=InnoDB;
CREATE INDEX ix_visita_status ON visita (status);
CREATE INDEX ix_visita_abertura ON visita (data_hora_abertura);

-- codigo_em_uso é uma coluna gerada: só tem valor enquanto a comanda está em uso.
-- O UNIQUE sobre ela impede duas pulseiras em uso com o mesmo número, mas permite
-- repetir o número depois que a pulseira é baixada ou perdida (a numeração volta a zero).
CREATE TABLE comanda (
    id_comanda      INT AUTO_INCREMENT,
    id_visita       INT         NOT NULL,
    codigo          INT         NOT NULL,
    status          VARCHAR(10) NOT NULL DEFAULT 'em uso',
    codigo_em_uso   INT GENERATED ALWAYS AS (IF(status = 'em uso', codigo, NULL)) STORED,
    CONSTRAINT pk_comanda PRIMARY KEY (id_comanda),
    CONSTRAINT uq_comanda_visita UNIQUE (id_visita),
    CONSTRAINT uq_comanda_codigo_em_uso UNIQUE (codigo_em_uso),
    CONSTRAINT ck_comanda_codigo CHECK (codigo BETWEEN 0 AND 9999),
    CONSTRAINT ck_comanda_status CHECK (status IN ('em uso', 'baixada', 'perdida')),
    CONSTRAINT fk_comanda_visita FOREIGN KEY (id_visita) REFERENCES visita (id_visita)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE controle_acesso (
    id_controle_acesso     INT AUTO_INCREMENT,
    id_visita              INT         NOT NULL,
    id_ambiente            INT         NOT NULL,
    data_hora_solicitacao  DATETIME    NOT NULL,
    data_hora_entrada      DATETIME    NULL,
    data_hora_saida        DATETIME    NULL,
    quant_pessoas          INT         NOT NULL,
    status                 VARCHAR(15) NOT NULL DEFAULT 'aguardando',
    CONSTRAINT pk_controle_acesso PRIMARY KEY (id_controle_acesso),
    CONSTRAINT ck_acesso_pessoas CHECK (quant_pessoas > 0),
    CONSTRAINT ck_acesso_status CHECK (status IN ('aguardando', 'no ambiente', 'encerrado', 'desistiu')),
    CONSTRAINT ck_acesso_entrada CHECK (data_hora_entrada IS NULL OR data_hora_entrada >= data_hora_solicitacao),
    CONSTRAINT ck_acesso_saida CHECK (data_hora_saida IS NULL
        OR (data_hora_entrada IS NOT NULL AND data_hora_saida >= data_hora_entrada)),
    CONSTRAINT ck_acesso_coerencia CHECK (
        (status = 'aguardando'  AND data_hora_entrada IS NULL     AND data_hora_saida IS NULL)
        OR (status = 'no ambiente' AND data_hora_entrada IS NOT NULL AND data_hora_saida IS NULL)
        OR (status = 'encerrado'   AND data_hora_entrada IS NOT NULL AND data_hora_saida IS NOT NULL)
        OR (status = 'desistiu'    AND data_hora_entrada IS NULL     AND data_hora_saida IS NULL)
    ),
    CONSTRAINT fk_acesso_visita FOREIGN KEY (id_visita) REFERENCES visita (id_visita)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_acesso_ambiente FOREIGN KEY (id_ambiente) REFERENCES ambiente (id_ambiente)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;
CREATE INDEX ix_acesso_status ON controle_acesso (status);
CREATE INDEX ix_acesso_solicitacao ON controle_acesso (data_hora_solicitacao);

CREATE TABLE funcionario (
    id_func    INT AUTO_INCREMENT,
    nome_func  VARCHAR(120) NOT NULL,
    cargo      VARCHAR(20)  NOT NULL,
    CONSTRAINT pk_funcionario PRIMARY KEY (id_func),
    CONSTRAINT ck_funcionario_cargo CHECK (cargo IN ('garçom', 'cumim', 'bar', 'caixa', 'cozinha',
        'sushiman', 'pizzaiolo', 'narguilé', 'valet', 'segurança', 'limpeza', 'RH', 'maître', 'gerente'))
) ENGINE=InnoDB;

CREATE TABLE caixa (
    id_caixa              INT AUTO_INCREMENT,
    id_func               INT           NOT NULL,
    data_hora_abertura    DATETIME      NOT NULL,
    valor_abertura        DECIMAL(10,2) NOT NULL DEFAULT 150.00,
    data_hora_fechamento  DATETIME      NULL,
    valor_fechamento      DECIMAL(10,2) NULL,
    status                VARCHAR(10)   NOT NULL DEFAULT 'aberto',
    CONSTRAINT pk_caixa PRIMARY KEY (id_caixa),
    CONSTRAINT ck_caixa_abertura CHECK (valor_abertura >= 0),
    CONSTRAINT ck_caixa_status CHECK (status IN ('aberto', 'fechado')),
    CONSTRAINT ck_caixa_fechamento CHECK (
        (status = 'aberto' AND data_hora_fechamento IS NULL AND valor_fechamento IS NULL)
        OR (status = 'fechado' AND data_hora_fechamento IS NOT NULL AND valor_fechamento IS NOT NULL
            AND valor_fechamento >= 0 AND data_hora_fechamento >= data_hora_abertura)
    ),
    CONSTRAINT fk_caixa_funcionario FOREIGN KEY (id_func) REFERENCES funcionario (id_func)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;
CREATE INDEX ix_caixa_status ON caixa (status);
CREATE INDEX ix_caixa_abertura ON caixa (data_hora_abertura);

CREATE TABLE pagamento (
    id_pgto             INT AUTO_INCREMENT,
    id_visita           INT           NOT NULL,
    id_caixa            INT           NOT NULL,
    valor_total         DECIMAL(10,2) NOT NULL,
    valor_taxa_servico  DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    forma_pgto          VARCHAR(20)   NOT NULL,
    data_hora           DATETIME      NOT NULL,
    numero_nf           VARCHAR(20)   NULL,
    CONSTRAINT pk_pagamento PRIMARY KEY (id_pgto),
    CONSTRAINT uq_pagamento_nf UNIQUE (numero_nf),
    CONSTRAINT ck_pagamento_total CHECK (valor_total > 0),
    CONSTRAINT ck_pagamento_taxa CHECK (valor_taxa_servico >= 0 AND valor_taxa_servico <= valor_total),
    CONSTRAINT ck_pagamento_forma CHECK (forma_pgto IN ('dinheiro', 'cartão de crédito', 'cartão de débito', 'pix', 'ticket')),
    CONSTRAINT fk_pagamento_visita FOREIGN KEY (id_visita) REFERENCES visita (id_visita)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_pagamento_caixa FOREIGN KEY (id_caixa) REFERENCES caixa (id_caixa)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;
CREATE INDEX ix_pagamento_data ON pagamento (data_hora);

CREATE TABLE categoria_prato (
    id_categ        INT AUTO_INCREMENT,
    nome            VARCHAR(60) NOT NULL,
    setor_producao  VARCHAR(20) NOT NULL,
    CONSTRAINT pk_categoria_prato PRIMARY KEY (id_categ),
    CONSTRAINT uq_categoria_nome UNIQUE (nome),
    CONSTRAINT ck_categoria_setor CHECK (setor_producao IN ('bar', 'cozinha', 'narguilé', 'comida japonesa', 'pizzaria'))
) ENGINE=InnoDB;

CREATE TABLE produto_estoque (
    id_produto      INT AUTO_INCREMENT,
    nome            VARCHAR(80) NOT NULL,
    qtd_atual       INT         NOT NULL DEFAULT 0,
    estoque_minimo  INT         NOT NULL DEFAULT 0,
    CONSTRAINT pk_produto_estoque PRIMARY KEY (id_produto),
    CONSTRAINT uq_produto_nome UNIQUE (nome),
    CONSTRAINT ck_produto_qtd CHECK (qtd_atual >= 0),
    CONSTRAINT ck_produto_minimo CHECK (estoque_minimo >= 0)
) ENGINE=InnoDB;

CREATE TABLE prato (
    id_prato    INT AUTO_INCREMENT,
    nome_prato  VARCHAR(80)   NOT NULL,
    preco       DECIMAL(10,2) NOT NULL,
    id_categ    INT           NOT NULL,
    id_produto  INT           NULL,
    CONSTRAINT pk_prato PRIMARY KEY (id_prato),
    CONSTRAINT ck_prato_preco CHECK (preco > 0),
    CONSTRAINT fk_prato_categoria FOREIGN KEY (id_categ) REFERENCES categoria_prato (id_categ)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_prato_produto FOREIGN KEY (id_produto) REFERENCES produto_estoque (id_produto)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE pedido (
    id_pedido  INT AUTO_INCREMENT,
    id_visita  INT         NOT NULL,
    id_func    INT         NOT NULL,
    data_hora  DATETIME    NOT NULL,
    status     VARCHAR(15) NOT NULL DEFAULT 'registrado',
    CONSTRAINT pk_pedido PRIMARY KEY (id_pedido),
    CONSTRAINT ck_pedido_status CHECK (status IN ('registrado', 'em preparo', 'pronto', 'entregue')),
    CONSTRAINT fk_pedido_visita FOREIGN KEY (id_visita) REFERENCES visita (id_visita)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_pedido_funcionario FOREIGN KEY (id_func) REFERENCES funcionario (id_func)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;
CREATE INDEX ix_pedido_status ON pedido (status);
CREATE INDEX ix_pedido_data ON pedido (data_hora);

CREATE TABLE item_pedido (
    id_item         INT AUTO_INCREMENT,
    id_pedido       INT           NOT NULL,
    id_prato        INT           NOT NULL,
    qtd             INT           NOT NULL,
    preco_unitario  DECIMAL(10,2) NOT NULL,
    observacao      VARCHAR(255)  NULL,
    status          VARCHAR(10)   NOT NULL DEFAULT 'ativo',
    CONSTRAINT pk_item_pedido PRIMARY KEY (id_item),
    CONSTRAINT ck_item_qtd CHECK (qtd > 0),
    CONSTRAINT ck_item_preco CHECK (preco_unitario > 0),
    CONSTRAINT ck_item_status CHECK (status IN ('ativo', 'cancelado')),
    CONSTRAINT fk_item_pedido FOREIGN KEY (id_pedido) REFERENCES pedido (id_pedido)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_item_prato FOREIGN KEY (id_prato) REFERENCES prato (id_prato)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE fornecedor (
    id_fornecedor  INT AUTO_INCREMENT,
    razao_social   VARCHAR(120) NOT NULL,
    cnpj           VARCHAR(18)  NOT NULL,
    telefone       VARCHAR(20)  NOT NULL,
    CONSTRAINT pk_fornecedor PRIMARY KEY (id_fornecedor),
    CONSTRAINT uq_fornecedor_cnpj UNIQUE (cnpj)
) ENGINE=InnoDB;

CREATE TABLE compra (
    id_compra         INT AUTO_INCREMENT,
    id_func           INT           NOT NULL,
    id_fornecedor     INT           NOT NULL,
    data_compra       DATE          NOT NULL,
    data_recebimento  DATE          NULL,
    valor_total       DECIMAL(10,2) NOT NULL,
    status            VARCHAR(10)   NOT NULL DEFAULT 'pedida',
    CONSTRAINT pk_compra PRIMARY KEY (id_compra),
    CONSTRAINT ck_compra_total CHECK (valor_total > 0),
    CONSTRAINT ck_compra_status CHECK (status IN ('pedida', 'recebida', 'cancelada')),
    CONSTRAINT ck_compra_recebimento CHECK (status <> 'recebida' OR data_recebimento IS NOT NULL),
    CONSTRAINT ck_compra_data CHECK (data_recebimento IS NULL OR data_recebimento >= data_compra),
    CONSTRAINT fk_compra_funcionario FOREIGN KEY (id_func) REFERENCES funcionario (id_func)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_compra_fornecedor FOREIGN KEY (id_fornecedor) REFERENCES fornecedor (id_fornecedor)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE item_compra (
    id_item_compra  INT AUTO_INCREMENT,
    id_compra       INT           NOT NULL,
    id_produto      INT           NOT NULL,
    qtd             INT           NOT NULL,
    custo_unitario  DECIMAL(10,2) NOT NULL,
    CONSTRAINT pk_item_compra PRIMARY KEY (id_item_compra),
    CONSTRAINT ck_item_compra_qtd CHECK (qtd > 0),
    CONSTRAINT ck_item_compra_custo CHECK (custo_unitario > 0),
    CONSTRAINT fk_item_compra_compra FOREIGN KEY (id_compra) REFERENCES compra (id_compra)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_item_compra_produto FOREIGN KEY (id_produto) REFERENCES produto_estoque (id_produto)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE movimentacao_estoque (
    id_movimentacao  INT AUTO_INCREMENT,
    id_func          INT          NOT NULL,
    id_produto       INT          NOT NULL,
    id_compra        INT          NULL,
    tipo             VARCHAR(20)  NOT NULL,
    qtd              INT          NOT NULL,
    motivo           VARCHAR(100) NULL,
    data_hora        DATETIME     NOT NULL,
    CONSTRAINT pk_movimentacao PRIMARY KEY (id_movimentacao),
    CONSTRAINT ck_mov_tipo CHECK (tipo IN ('entrada', 'saída', 'ajuste positivo', 'ajuste negativo')),
    CONSTRAINT ck_mov_qtd CHECK (qtd > 0),
    CONSTRAINT ck_mov_motivo CHECK (tipo NOT IN ('ajuste positivo', 'ajuste negativo') OR motivo IS NOT NULL),
    CONSTRAINT ck_mov_compra CHECK (id_compra IS NULL OR tipo = 'entrada'),
    CONSTRAINT fk_mov_funcionario FOREIGN KEY (id_func) REFERENCES funcionario (id_func)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_mov_produto FOREIGN KEY (id_produto) REFERENCES produto_estoque (id_produto)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_mov_compra FOREIGN KEY (id_compra) REFERENCES compra (id_compra)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;
CREATE INDEX ix_mov_data ON movimentacao_estoque (data_hora);

-- Tabelas associativas dos dois relacionamentos N:N
CREATE TABLE mesa_visita (
    id_mesa    INT NOT NULL,
    id_visita  INT NOT NULL,
    CONSTRAINT pk_mesa_visita PRIMARY KEY (id_mesa, id_visita),
    CONSTRAINT fk_mesa_visita_mesa FOREIGN KEY (id_mesa) REFERENCES mesa (id_mesa)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_mesa_visita_visita FOREIGN KEY (id_visita) REFERENCES visita (id_visita)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE funcionario_pagamento (
    id_func  INT NOT NULL,
    id_pgto  INT NOT NULL,
    CONSTRAINT pk_funcionario_pagamento PRIMARY KEY (id_func, id_pgto),
    CONSTRAINT fk_func_pgto_funcionario FOREIGN KEY (id_func) REFERENCES funcionario (id_func)
        ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_func_pgto_pagamento FOREIGN KEY (id_pgto) REFERENCES pagamento (id_pgto)
        ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

