-- ---------------------------------------------------------------------
-- 4. SELECT com JOIN (consultas que cruzam várias tabelas)
-- ---------------------------------------------------------------------

-- S01 — Qual é o detalhe da conta da visita 100 (pedidos, itens, preço do momento e garçom)?
SELECT v.id_visita, c.codigo AS pulseira, p.id_pedido, p.data_hora, f.nome_func AS garcom,
       pr.nome_prato, cp.nome AS categoria, i.qtd, i.preco_unitario,
       i.qtd * i.preco_unitario AS subtotal, i.observacao, i.status AS status_item
FROM visita v
JOIN comanda c        ON c.id_visita = v.id_visita
JOIN pedido p         ON p.id_visita = v.id_visita
JOIN funcionario f    ON f.id_func = p.id_func
JOIN item_pedido i    ON i.id_pedido = p.id_pedido
JOIN prato pr         ON pr.id_prato = i.id_prato
JOIN categoria_prato cp ON cp.id_categ = pr.id_categ
WHERE v.id_visita = 100
ORDER BY p.data_hora, i.id_item;

-- S02 — Quais mesas estão ocupadas agora, em que ambiente, com qual pulseira e qual consumo acumulado?
SELECT a.nome_ambiente, m.numero AS mesa, c.codigo AS pulseira, v.data_hora_abertura,
       (SELECT COALESCE(SUM(i.qtd * i.preco_unitario), 0)
          FROM pedido p JOIN item_pedido i ON i.id_pedido = p.id_pedido
         WHERE p.id_visita = v.id_visita AND i.status = 'ativo') AS consumo_acumulado
FROM visita v
JOIN comanda c      ON c.id_visita = v.id_visita
JOIN mesa_visita mv ON mv.id_visita = v.id_visita
JOIN mesa m         ON m.id_mesa = mv.id_mesa
JOIN ambiente a     ON a.id_ambiente = m.id_ambiente
WHERE v.status = 'aberta'
ORDER BY a.nome_ambiente, m.numero;

-- S03 — Quais itens foram cancelados, em que setor, por qual garçom e de quanto era o valor?
SELECT p.data_hora, f.nome_func AS garcom, cp.setor_producao, pr.nome_prato,
       i.qtd, i.preco_unitario, i.qtd * i.preco_unitario AS valor_cancelado
FROM item_pedido i
JOIN pedido p           ON p.id_pedido = i.id_pedido
JOIN funcionario f      ON f.id_func = p.id_func
JOIN prato pr           ON pr.id_prato = i.id_prato
JOIN categoria_prato cp ON cp.id_categ = pr.id_categ
WHERE i.status = 'cancelado'
ORDER BY p.data_hora
LIMIT 20;

-- S04 — Quais compras foram feitas, de qual fornecedor, por quem e com quais produtos?
SELECT c.id_compra, c.data_compra, c.data_recebimento, c.status, fo.razao_social,
       fu.nome_func AS comprador, pe.nome AS produto, ic.qtd, ic.custo_unitario,
       ic.qtd * ic.custo_unitario AS valor_item
FROM compra c
JOIN fornecedor fo     ON fo.id_fornecedor = c.id_fornecedor
JOIN funcionario fu    ON fu.id_func = c.id_func
JOIN item_compra ic    ON ic.id_compra = c.id_compra
JOIN produto_estoque pe ON pe.id_produto = ic.id_produto
ORDER BY c.data_compra, c.id_compra
LIMIT 20;

-- S05 — Quais pagamentos foram feitos em cada caixa, por quem e de que forma (incluindo divisão de conta)?
SELECT cx.id_caixa, cx.data_hora_abertura, op.nome_func AS operador_caixa,
       p.id_pgto, p.id_visita, p.forma_pgto, p.valor_total, p.valor_taxa_servico, p.numero_nf,
       GROUP_CONCAT(f.nome_func ORDER BY f.nome_func SEPARATOR ' / ') AS quem_recebeu
FROM pagamento p
JOIN caixa cx                  ON cx.id_caixa = p.id_caixa
JOIN funcionario op            ON op.id_func = cx.id_func
JOIN funcionario_pagamento fp  ON fp.id_pgto = p.id_pgto
JOIN funcionario f             ON f.id_func = fp.id_func
GROUP BY cx.id_caixa, cx.data_hora_abertura, op.nome_func, p.id_pgto, p.id_visita,
         p.forma_pgto, p.valor_total, p.valor_taxa_servico, p.numero_nf
ORDER BY p.data_hora
LIMIT 20;

-- ---------------------------------------------------------------------
-- 5. UPDATE
-- ---------------------------------------------------------------------

-- U01 — Os pedidos recém-registrados das visitas abertas foram enviados ao setor: passam para "em preparo".
UPDATE pedido
   SET status = 'em preparo'
 WHERE status = 'registrado'
   AND id_visita IN (SELECT id_visita FROM visita WHERE status = 'aberta');

-- U02 — Reajuste de 5% nos pratos da cozinha que ainda não foram vendidos.
--       Os itens já vendidos mantêm o preço do momento (item_pedido.preco_unitario).
UPDATE prato
   SET preco = ROUND(preco * 1.05, 2)
 WHERE id_categ = 2
   AND id_prato NOT IN (SELECT id_prato FROM item_pedido);

-- U03 — A gerência aumenta em 5 unidades o estoque mínimo dos produtos zerados (ruptura).
UPDATE produto_estoque
   SET estoque_minimo = estoque_minimo + 5
 WHERE qtd_atual = 0;

-- ---------------------------------------------------------------------
-- 6. DELETE
-- ---------------------------------------------------------------------

-- D01 — Remove um fornecedor cadastrado por engano que nunca recebeu compra.
DELETE FROM fornecedor
 WHERE id_fornecedor = 49
   AND NOT EXISTS (SELECT 1 FROM compra WHERE compra.id_fornecedor = fornecedor.id_fornecedor);

