-- ---------------------------------------------------------------------
-- 7. CONSULTAS GERENCIAIS
-- Período da massa: 26/10/2026 (segunda) a 01/11/2026 (domingo).
-- ---------------------------------------------------------------------

-- Visão auxiliar: ambiente de cada visita = ambiente da mesa de menor id_mesa.
CREATE OR REPLACE VIEW vw_visita_ambiente AS
SELECT mv.id_visita, m.id_ambiente
FROM mesa_visita mv
JOIN mesa m ON m.id_mesa = mv.id_mesa
WHERE mv.id_mesa = (SELECT MIN(x.id_mesa) FROM mesa_visita x WHERE x.id_visita = mv.id_visita);

-- G01 — Qual é a taxa de ocupação de cada ambiente em um dado momento (domingo, 21h)?
-- Atende: P1 (controle de acesso) e K1 (taxa de ocupação por ambiente)
SET @momento = '2026-11-01 21:00:00';
SELECT a.nome_ambiente, a.capacidade_maxima,
       COALESCE(SUM(ca.quant_pessoas), 0) AS pessoas_no_ambiente,
       ROUND(100 * COALESCE(SUM(ca.quant_pessoas), 0) / a.capacidade_maxima, 1) AS taxa_ocupacao_pct
FROM ambiente a
LEFT JOIN controle_acesso ca
       ON ca.id_ambiente = a.id_ambiente
      AND ca.data_hora_entrada <= @momento
      AND (ca.data_hora_saida IS NULL OR ca.data_hora_saida > @momento)
GROUP BY a.id_ambiente, a.nome_ambiente, a.capacidade_maxima
ORDER BY a.id_ambiente;

-- G02 — Quanto o cliente espera, em média, para entrar em cada ambiente, por dia?
-- Atende: P1 (tempo de espera do Deck) e K2 (tempo médio de espera na fila)
SELECT a.nome_ambiente, DATE(ca.data_hora_solicitacao) AS dia,
       COUNT(*) AS entradas,
       ROUND(AVG(TIMESTAMPDIFF(MINUTE, ca.data_hora_solicitacao, ca.data_hora_entrada)), 1) AS espera_media_min,
       MAX(TIMESTAMPDIFF(MINUTE, ca.data_hora_solicitacao, ca.data_hora_entrada)) AS espera_maxima_min
FROM controle_acesso ca
JOIN ambiente a ON a.id_ambiente = ca.id_ambiente
WHERE ca.data_hora_entrada IS NOT NULL
GROUP BY a.id_ambiente, a.nome_ambiente, DATE(ca.data_hora_solicitacao)
ORDER BY a.nome_ambiente, dia;

-- G03 — Qual percentual de clientes desiste da fila em cada ambiente, por semana?
-- Atende: P1 (fila do Deck) e K3 (taxa de desistência)
SELECT a.nome_ambiente, YEARWEEK(ca.data_hora_solicitacao, 1) AS semana,
       COUNT(*) AS solicitacoes,
       SUM(ca.status = 'desistiu') AS desistencias,
       ROUND(100 * SUM(ca.status = 'desistiu') / COUNT(*), 1) AS taxa_desistencia_pct
FROM controle_acesso ca
JOIN ambiente a ON a.id_ambiente = ca.id_ambiente
GROUP BY a.id_ambiente, a.nome_ambiente, YEARWEEK(ca.data_hora_solicitacao, 1)
ORDER BY a.nome_ambiente;

-- G04 — Quais bebidas estão no estoque mínimo ou abaixo dele hoje?
-- Atende: P2 (ruptura de estoque de bebidas) e K4 (produtos abaixo do estoque mínimo)
SELECT id_produto, nome, qtd_atual, estoque_minimo, estoque_minimo - qtd_atual AS falta_para_o_minimo
FROM produto_estoque
WHERE qtd_atual <= estoque_minimo
ORDER BY qtd_atual, nome;

-- G05 — Qual percentual das movimentações de estoque são ajustes de conferência, por mês?
-- Atende: P2 (divergências de estoque) e K5 (taxa de ajustes de estoque)
SELECT DATE_FORMAT(data_hora, '%Y-%m') AS mes,
       SUM(CASE WHEN tipo IN ('ajuste positivo', 'ajuste negativo') THEN qtd ELSE 0 END) AS unidades_ajustadas,
       SUM(qtd) AS unidades_movimentadas,
       ROUND(100 * SUM(CASE WHEN tipo IN ('ajuste positivo', 'ajuste negativo') THEN qtd ELSE 0 END) / SUM(qtd), 2) AS taxa_ajustes_pct
FROM movimentacao_estoque
GROUP BY DATE_FORMAT(data_hora, '%Y-%m');

-- G06 — Qual é o consumo médio diário de cada bebida (saídas por requisição do bar)?
-- Atende: P2 (controle de estoque) e K6 (consumo médio diário de bebidas)
SELECT pe.nome, SUM(m.qtd) AS saidas_no_periodo,
       ROUND(SUM(m.qtd) / dias.qtd_dias, 1) AS consumo_medio_diario
FROM movimentacao_estoque m
JOIN produto_estoque pe ON pe.id_produto = m.id_produto
CROSS JOIN (SELECT DATEDIFF(MAX(data_hora), MIN(data_hora)) + 1 AS qtd_dias
              FROM movimentacao_estoque WHERE tipo = 'saída') dias
WHERE m.tipo = 'saída'
GROUP BY pe.id_produto, pe.nome, dias.qtd_dias
ORDER BY consumo_medio_diario DESC
LIMIT 15;

-- G07 — Qual é o ticket médio (valor pago por visita) em cada ambiente, por dia?
-- Atende: K7 (ticket médio por ambiente)
SELECT a.nome_ambiente, DATE(p.data_hora) AS dia,
       COUNT(DISTINCT p.id_visita) AS visitas_pagas,
       ROUND(SUM(p.valor_total), 2) AS total_pago,
       ROUND(SUM(p.valor_total) / COUNT(DISTINCT p.id_visita), 2) AS ticket_medio
FROM pagamento p
JOIN vw_visita_ambiente va ON va.id_visita = p.id_visita
JOIN ambiente a ON a.id_ambiente = va.id_ambiente
GROUP BY a.id_ambiente, a.nome_ambiente, DATE(p.data_hora)
ORDER BY a.nome_ambiente, dia;

-- G08 — Qual é a taxa de cancelamento de itens, por setor de produção e semana?
-- Atende: K8 (taxa de cancelamento de itens)
SELECT YEARWEEK(p.data_hora, 1) AS semana, cp.setor_producao,
       COUNT(*) AS itens, SUM(i.status = 'cancelado') AS cancelados,
       ROUND(100 * SUM(i.status = 'cancelado') / COUNT(*), 2) AS taxa_cancelamento_pct
FROM item_pedido i
JOIN pedido p           ON p.id_pedido = i.id_pedido
JOIN prato pr           ON pr.id_prato = i.id_prato
JOIN categoria_prato cp ON cp.id_categ = pr.id_categ
GROUP BY YEARWEEK(p.data_hora, 1), cp.setor_producao
ORDER BY cp.setor_producao;

-- G09 — Quanto saiu do estoque além (ou aquém) do que foi vendido, por bebida vendida como vem?
-- Atende: P2 (controle de estoque de bebidas) e K9 (diferença entre saídas de estoque e vendas)
WITH saidas AS (
    SELECT id_produto, SUM(qtd) AS qtd_saida
    FROM movimentacao_estoque WHERE tipo = 'saída' GROUP BY id_produto
), vendas AS (
    SELECT pr.id_produto, SUM(i.qtd) AS qtd_vendida
    FROM item_pedido i JOIN prato pr ON pr.id_prato = i.id_prato
    WHERE i.status = 'ativo' AND pr.id_produto IS NOT NULL
    GROUP BY pr.id_produto
)
SELECT pe.nome, COALESCE(s.qtd_saida, 0) AS saidas, COALESCE(v.qtd_vendida, 0) AS vendidas,
       COALESCE(s.qtd_saida, 0) - COALESCE(v.qtd_vendida, 0) AS diferenca
FROM produto_estoque pe
LEFT JOIN saidas s ON s.id_produto = pe.id_produto
LEFT JOIN vendas v ON v.id_produto = pe.id_produto
WHERE COALESCE(s.qtd_saida, 0) <> COALESCE(v.qtd_vendida, 0)
ORDER BY ABS(COALESCE(s.qtd_saida, 0) - COALESCE(v.qtd_vendida, 0)) DESC
LIMIT 15;

-- G10 — Qual é o faturamento por ambiente e por hora do dia?
-- Atende: K10 (faturamento por ambiente e hora)
SELECT a.nome_ambiente, HOUR(p.data_hora) AS hora, ROUND(SUM(p.valor_total), 2) AS faturamento
FROM pagamento p
JOIN vw_visita_ambiente va ON va.id_visita = p.id_visita
JOIN ambiente a ON a.id_ambiente = va.id_ambiente
GROUP BY a.id_ambiente, a.nome_ambiente, HOUR(p.data_hora)
ORDER BY a.nome_ambiente, hora;

-- G11 — Qual percentual dos pagamentos está sem número de nota fiscal, por mês?
-- Atende: K11 (pagamentos sem número de nota fiscal)
SELECT DATE_FORMAT(data_hora, '%Y-%m') AS mes, COUNT(*) AS pagamentos,
       SUM(numero_nf IS NULL) AS sem_nota,
       ROUND(100 * SUM(numero_nf IS NULL) / COUNT(*), 2) AS pct_sem_nota
FROM pagamento
GROUP BY DATE_FORMAT(data_hora, '%Y-%m');

-- G12 — Qual foi a diferença de caixa no fechamento de cada turno?
-- Atende: K12 (diferença de caixa no fechamento)
SELECT cx.id_caixa, cx.data_hora_abertura, f.nome_func AS operador, cx.valor_abertura,
       COALESCE(SUM(CASE WHEN p.forma_pgto = 'dinheiro' THEN p.valor_total END), 0) AS recebido_em_dinheiro,
       cx.valor_fechamento,
       cx.valor_fechamento - (cx.valor_abertura + COALESCE(SUM(CASE WHEN p.forma_pgto = 'dinheiro' THEN p.valor_total END), 0)) AS diferenca
FROM caixa cx
JOIN funcionario f ON f.id_func = cx.id_func
LEFT JOIN pagamento p ON p.id_caixa = cx.id_caixa
WHERE cx.status = 'fechado'
GROUP BY cx.id_caixa, cx.data_hora_abertura, f.nome_func, cx.valor_abertura, cx.valor_fechamento
ORDER BY ABS(cx.valor_fechamento - (cx.valor_abertura + COALESCE(SUM(CASE WHEN p.forma_pgto = 'dinheiro' THEN p.valor_total END), 0))) DESC, cx.id_caixa
LIMIT 10;

-- G13 — Quanto foi gasto com compras em cada fornecedor, por mês (sem compras canceladas)?
-- Atende: K13 (gasto de compras por fornecedor)
SELECT DATE_FORMAT(c.data_compra, '%Y-%m') AS mes, fo.razao_social,
       COUNT(DISTINCT c.id_compra) AS compras, SUM(ic.qtd * ic.custo_unitario) AS gasto
FROM compra c
JOIN fornecedor fo  ON fo.id_fornecedor = c.id_fornecedor
JOIN item_compra ic ON ic.id_compra = c.id_compra
WHERE c.status <> 'cancelada'
GROUP BY DATE_FORMAT(c.data_compra, '%Y-%m'), fo.id_fornecedor, fo.razao_social
ORDER BY gasto DESC
LIMIT 15;

-- G14 — Quantos dias cada fornecedor leva, em média, para entregar?
-- Atende: K14 (prazo médio de recebimento da mercadoria)
SELECT fo.razao_social, COUNT(*) AS compras_recebidas,
       ROUND(AVG(DATEDIFF(c.data_recebimento, c.data_compra)), 1) AS prazo_medio_dias
FROM compra c
JOIN fornecedor fo ON fo.id_fornecedor = c.id_fornecedor
WHERE c.status = 'recebida'
GROUP BY fo.id_fornecedor, fo.razao_social
ORDER BY prazo_medio_dias DESC, fo.razao_social
LIMIT 15;

-- G15 — Qual é o faturamento por dia e por forma de pagamento?
-- Atende: K15 (faturamento por período e forma de pagamento)
SELECT DATE(data_hora) AS dia, forma_pgto, COUNT(*) AS pagamentos, ROUND(SUM(valor_total), 2) AS faturamento
FROM pagamento
GROUP BY DATE(data_hora), forma_pgto
ORDER BY dia, faturamento DESC;

-- G16 — Quanto cada visita consumiu e em quais mesas esteve (os 20 maiores consumos)?
-- Atende: K16 (consumo por visita e mesa)
SELECT v.id_visita, c.codigo AS pulseira, a.nome_ambiente,
       GROUP_CONCAT(DISTINCT m.numero ORDER BY m.numero SEPARATOR ', ') AS mesas,
       v.data_hora_abertura, ROUND(SUM(i.qtd * i.preco_unitario), 2) AS consumo
FROM visita v
JOIN comanda c      ON c.id_visita = v.id_visita
JOIN mesa_visita mv ON mv.id_visita = v.id_visita
JOIN mesa m         ON m.id_mesa = mv.id_mesa
JOIN ambiente a     ON a.id_ambiente = m.id_ambiente
JOIN pedido p       ON p.id_visita = v.id_visita
JOIN item_pedido i  ON i.id_pedido = p.id_pedido AND i.status = 'ativo'
GROUP BY v.id_visita, c.codigo, a.nome_ambiente, v.data_hora_abertura
ORDER BY consumo DESC
LIMIT 20;

-- ---------------------------------------------------------------------
-- 8. CONSULTAS DE AUDITORIA
-- Uma consulta de auditoria que retorna zero linhas indica que a regra está sendo cumprida.
-- ---------------------------------------------------------------------

-- A01 — Existe visita sem nenhuma mesa?
-- Verifica: RN05 (toda visita ocupa ao menos uma mesa)
SELECT v.id_visita FROM visita v
WHERE NOT EXISTS (SELECT 1 FROM mesa_visita mv WHERE mv.id_visita = v.id_visita);

-- A02 — Existe pedido sem nenhum item?
-- Verifica: RN09 (todo pedido tem ao menos um item)
SELECT p.id_pedido FROM pedido p
WHERE NOT EXISTS (SELECT 1 FROM item_pedido i WHERE i.id_pedido = p.id_pedido);

-- A03 — Existe compra sem nenhum item?
-- Verifica: RN24 (toda compra tem ao menos um item)
SELECT c.id_compra FROM compra c
WHERE NOT EXISTS (SELECT 1 FROM item_compra ic WHERE ic.id_compra = c.id_compra);

-- A04 — Existe pagamento sem funcionário que o recebeu?
-- Verifica: RN18 (o garçom ou o caixa recebe o pagamento) e RN29 (toda operação identifica o funcionário)
SELECT p.id_pgto FROM pagamento p
WHERE NOT EXISTS (SELECT 1 FROM funcionario_pagamento fp WHERE fp.id_pgto = p.id_pgto);

-- A05 — Existe visita fechada sem pagamento, ou visita aberta com pagamento?
-- Verifica: RN04 (a visita só fecha depois de a conta ser quitada)
SELECT v.id_visita, v.status,
       (SELECT COUNT(*) FROM pagamento p WHERE p.id_visita = v.id_visita) AS pagamentos
FROM visita v
WHERE (v.status = 'fechada' AND NOT EXISTS (SELECT 1 FROM pagamento p WHERE p.id_visita = v.id_visita))
   OR (v.status = 'aberta'  AND EXISTS (SELECT 1 FROM pagamento p WHERE p.id_visita = v.id_visita));

-- A06 — Existe ambiente ativo sem mesa?
-- Verifica: RN05 (cada mesa pertence a um ambiente; todo ambiente tem mesas)
SELECT a.id_ambiente, a.nome_ambiente FROM ambiente a
WHERE a.status = 'ativo' AND NOT EXISTS (SELECT 1 FROM mesa m WHERE m.id_ambiente = a.id_ambiente);

-- A07 — Existe categoria do cardápio sem nenhum prato?
-- Verifica: RN12 (cada prato pertence a uma única categoria; nenhuma categoria vazia)
SELECT cp.id_categ, cp.nome FROM categoria_prato cp
WHERE NOT EXISTS (SELECT 1 FROM prato pr WHERE pr.id_categ = cp.id_categ);

-- A08 — A soma dos pagamentos de alguma visita fechada é diferente do consumo mais a taxa?
-- Verifica: RN17 (a soma dos pagamentos da visita corresponde ao consumo mais a taxa)
SELECT v.id_visita, ROUND(SUM(p.valor_total), 2) AS pago,
       ROUND(c.consumo * 1.10, 2) AS consumo_mais_taxa
FROM visita v
JOIN pagamento p ON p.id_visita = v.id_visita
JOIN (SELECT pe.id_visita, SUM(i.qtd * i.preco_unitario) AS consumo
        FROM pedido pe JOIN item_pedido i ON i.id_pedido = pe.id_pedido AND i.status = 'ativo'
       GROUP BY pe.id_visita) c ON c.id_visita = v.id_visita
WHERE v.status = 'fechada'
GROUP BY v.id_visita, c.consumo
HAVING ABS(SUM(p.valor_total) - c.consumo * 1.10) > 0.05;

-- A09 — A taxa de serviço registrada de alguma visita é diferente de 10% do consumo?
-- Verifica: RN15 (a taxa de serviço é de 10% do consumo)
SELECT v.id_visita, ROUND(SUM(p.valor_taxa_servico), 2) AS taxa_registrada,
       ROUND(c.consumo * 0.10, 2) AS taxa_esperada
FROM visita v
JOIN pagamento p ON p.id_visita = v.id_visita
JOIN (SELECT pe.id_visita, SUM(i.qtd * i.preco_unitario) AS consumo
        FROM pedido pe JOIN item_pedido i ON i.id_pedido = pe.id_pedido AND i.status = 'ativo'
       GROUP BY pe.id_visita) c ON c.id_visita = v.id_visita
GROUP BY v.id_visita, c.consumo
HAVING ABS(SUM(p.valor_taxa_servico) - c.consumo * 0.10) > 0.05;

-- A10 — O valor total de alguma compra é diferente da soma dos seus itens?
-- Verifica: RN24 (a compra e seus itens; o total confere com a soma, base do KPI K13)
SELECT c.id_compra, c.valor_total, SUM(ic.qtd * ic.custo_unitario) AS soma_itens
FROM compra c JOIN item_compra ic ON ic.id_compra = c.id_compra
GROUP BY c.id_compra, c.valor_total
HAVING c.valor_total <> SUM(ic.qtd * ic.custo_unitario);

-- A11 — A quantidade atual de algum produto é diferente da soma das movimentações?
-- Verifica: RN20 e RN21 (saídas e ajustes registrados; a movimentação explica o saldo)
SELECT pe.id_produto, pe.nome, pe.qtd_atual,
       COALESCE(SUM(CASE WHEN m.tipo IN ('entrada', 'ajuste positivo') THEN m.qtd ELSE -m.qtd END), 0) AS saldo_pelas_movimentacoes
FROM produto_estoque pe
LEFT JOIN movimentacao_estoque m ON m.id_produto = pe.id_produto
GROUP BY pe.id_produto, pe.nome, pe.qtd_atual
HAVING pe.qtd_atual <> COALESCE(SUM(CASE WHEN m.tipo IN ('entrada', 'ajuste positivo') THEN m.qtd ELSE -m.qtd END), 0);

-- A12 — Existem duas pulseiras em uso com o mesmo número?
-- Verifica: RN02 (o número da pulseira é único entre as comandas em uso)
SELECT codigo, COUNT(*) AS comandas_em_uso FROM comanda
WHERE status = 'em uso' GROUP BY codigo HAVING COUNT(*) > 1;

-- A13 — Existe visita fechada com pulseira ainda em uso, ou visita aberta com pulseira baixada?
-- Verifica: RN04 (a pulseira é baixada pelo caixa na saída)
SELECT v.id_visita, v.status AS status_visita, c.codigo, c.status AS status_comanda
FROM visita v JOIN comanda c ON c.id_visita = v.id_visita
WHERE (v.status = 'fechada' AND c.status = 'em uso') OR (v.status = 'aberta' AND c.status = 'baixada');

-- A14 — Existe acesso com entrada antes da solicitação ou saída antes da entrada?
-- Verifica: RN06 (toda entrada e toda saída são registradas, em ordem cronológica)
SELECT id_controle_acesso, id_visita, data_hora_solicitacao, data_hora_entrada, data_hora_saida
FROM controle_acesso
WHERE data_hora_entrada < data_hora_solicitacao
   OR data_hora_saida < data_hora_entrada
   OR (data_hora_saida IS NOT NULL AND data_hora_entrada IS NULL);

-- A15 — Algum ambiente passou da sua capacidade máxima em algum momento de entrada?
-- Verifica: RN07 (um ambiente não recebe mais pessoas do que a sua capacidade)
SELECT a.nome_ambiente, ca.data_hora_entrada AS momento, a.capacidade_maxima,
       SUM(o.quant_pessoas) AS pessoas_no_ambiente
FROM controle_acesso ca
JOIN ambiente a ON a.id_ambiente = ca.id_ambiente
JOIN controle_acesso o ON o.id_ambiente = ca.id_ambiente
 AND o.data_hora_entrada <= ca.data_hora_entrada
 AND (o.data_hora_saida IS NULL OR o.data_hora_saida > ca.data_hora_entrada)
WHERE ca.data_hora_entrada IS NOT NULL
GROUP BY a.id_ambiente, a.nome_ambiente, a.capacidade_maxima, ca.id_controle_acesso, ca.data_hora_entrada
HAVING SUM(o.quant_pessoas) > a.capacidade_maxima;

-- A16 — Quais pagamentos estão sem número de nota fiscal?
-- Verifica: RN16 (todo pagamento tem nota fiscal e o número é registrado)
SELECT p.id_pgto, p.id_visita, p.data_hora, p.forma_pgto, p.valor_total, f.nome_func AS operador_caixa
FROM pagamento p
JOIN caixa cx ON cx.id_caixa = p.id_caixa
JOIN funcionario f ON f.id_func = cx.id_func
WHERE p.numero_nf IS NULL
ORDER BY p.data_hora;

-- A17 — Existe pagamento registrado fora do período de funcionamento do caixa?
-- Verifica: RN18 (todo pagamento é finalizado em um caixa) e RN19 (caixa aberto no período do turno)
SELECT p.id_pgto, p.data_hora, cx.id_caixa, cx.data_hora_abertura, cx.data_hora_fechamento
FROM pagamento p JOIN caixa cx ON cx.id_caixa = p.id_caixa
WHERE p.data_hora < cx.data_hora_abertura
   OR (cx.data_hora_fechamento IS NOT NULL AND p.data_hora > cx.data_hora_fechamento);

-- A18 — Alguma compra recebida não gerou a entrada de estoque na quantidade comprada?
-- Verifica: RN25 (no recebimento, as entradas no estoque ficam ligadas à compra)
SELECT c.id_compra, ic.id_produto, ic.qtd AS qtd_comprada,
       COALESCE(SUM(m.qtd), 0) AS qtd_entrada
FROM compra c
JOIN item_compra ic ON ic.id_compra = c.id_compra
LEFT JOIN movimentacao_estoque m
       ON m.id_compra = c.id_compra AND m.id_produto = ic.id_produto AND m.tipo = 'entrada'
WHERE c.status = 'recebida'
GROUP BY c.id_compra, ic.id_produto, ic.qtd
HAVING ic.qtd <> COALESCE(SUM(m.qtd), 0);

-- A19 — Quais itens foram vendidos por um preço diferente do preço atual do prato?
-- Verifica: RN10 (o preço do momento fica registrado no item, mesmo se o cardápio mudar depois)
SELECT pr.nome_prato, pr.preco AS preco_atual, i.preco_unitario AS preco_cobrado,
       COUNT(*) AS itens, MIN(p.data_hora) AS primeira_venda, MAX(p.data_hora) AS ultima_venda
FROM item_pedido i
JOIN pedido p ON p.id_pedido = i.id_pedido
JOIN prato pr ON pr.id_prato = i.id_prato
WHERE i.preco_unitario <> pr.preco
GROUP BY pr.id_prato, pr.nome_prato, pr.preco, i.preco_unitario
ORDER BY pr.nome_prato;

-- A20 — Existe produto no estoque mínimo ou abaixo dele sem compra pendente?
-- Verifica: RN22 (produto no mínimo é sinalizado e deve ser reposto)
SELECT pe.id_produto, pe.nome, pe.qtd_atual, pe.estoque_minimo
FROM produto_estoque pe
WHERE pe.qtd_atual <= pe.estoque_minimo
  AND NOT EXISTS (SELECT 1 FROM compra c JOIN item_compra ic ON ic.id_compra = c.id_compra
                   WHERE ic.id_produto = pe.id_produto AND c.status = 'pedida');

-- A21 — Alguma mesa foi ocupada por duas visitas ao mesmo tempo?
-- Verifica: RN05 (ocupação das mesas por visita: uma mesa não atende duas visitas ao mesmo tempo)
SELECT m.numero AS mesa, ca1.id_visita AS visita_1, ca2.id_visita AS visita_2
FROM mesa_visita mv1
JOIN mesa_visita mv2 ON mv2.id_mesa = mv1.id_mesa AND mv2.id_visita > mv1.id_visita
JOIN mesa m ON m.id_mesa = mv1.id_mesa
JOIN controle_acesso ca1 ON ca1.id_visita = mv1.id_visita AND ca1.data_hora_entrada IS NOT NULL
JOIN controle_acesso ca2 ON ca2.id_visita = mv2.id_visita AND ca2.data_hora_entrada IS NOT NULL
WHERE ca1.data_hora_entrada < COALESCE(ca2.data_hora_saida, '9999-12-31')
  AND ca2.data_hora_entrada < COALESCE(ca1.data_hora_saida, '9999-12-31');

-- A22 — As contas das pulseiras perdidas podem ser localizadas pelo garçom e pela mesa?
-- Verifica: RN03 (na perda da pulseira, a conta é localizada pelo garçom que tirou o pedido e pela mesa)
SELECT c.codigo AS pulseira_perdida, v.id_visita, GROUP_CONCAT(DISTINCT m.numero ORDER BY m.numero) AS mesas,
       GROUP_CONCAT(DISTINCT f.nome_func ORDER BY f.nome_func SEPARATOR ' / ') AS garcons,
       COUNT(DISTINCT p.id_pedido) AS pedidos
FROM comanda c
JOIN visita v       ON v.id_visita = c.id_visita
JOIN mesa_visita mv ON mv.id_visita = v.id_visita
JOIN mesa m         ON m.id_mesa = mv.id_mesa
LEFT JOIN pedido p  ON p.id_visita = v.id_visita
LEFT JOIN funcionario f ON f.id_func = p.id_func
WHERE c.status = 'perdida'
GROUP BY c.codigo, v.id_visita;
